+static int sdt_attach(struct bpf_program *obs)
+{
+	LIBBPF_OPTS(bpf_link_create_opts, opts);
+
+	return bpf_link_create(bpf_program__fd(obs), 0, BPF_TRACE_SDT, &opts);
+}
