+	ASSERT_EQ(skel->bss->xdp_len, sizeof(pkt), "xdp_len");
+	ASSERT_EQ(skel->bss->xdp_ret, XDP_PASS, "xdp_ret");
+
+out_link:
+	close(link);
+out_obs:
+	bpf_sdt_observer__destroy(skel);
+out_tgt:
