+	err = err ? : bpf_object__create_sdt_maps(obj);
 	err = err ? : bpf_object_prepare_progs(obj);
 
 	if (err) {
@@ -9893,8 +10029,11 @@ void bpf_object__close(struct bpf_object *obj)
