 drivers/gpu/drm/bridge/lontium-lt9611uxd.c | 1140 ++++++++++++++++++++
 2 files changed, 1141 insertions(+)
 create mode 100644 drivers/gpu/drm/bridge/lontium-lt9611uxd.c

diff --git a/drivers/gpu/drm/bridge/Makefile b/drivers/gpu/drm/bridge/Makefile
index 15cc821d85b7..8ea14c6404f3 100644
--- a/drivers/gpu/drm/bridge/Makefile
+++ b/drivers/gpu/drm/bridge/Makefile
@@ -17,6 +17,7 @@ obj-$(CONFIG_DRM_LONTIUM_LT8912B) += lontium-lt8912b.o
 obj-$(CONFIG_DRM_LONTIUM_LT9211) += lontium-lt9211.o
