 	VM_WARN_ON_ONCE_PAGE(__page_count_is_frozen(ret + 1), page);
 
+	if (ret)
+		ret = !atomic_cmpxchg_relaxed(&page->_refcount, 0, PAGEREF_FROZEN_BIT);
